## 📚 도서관 시스템으로 보는 OOP

### 1. 캡슐화 예시
```python
class BankAccount:
    def __init__(self, owner, initial_balance=0):
        self.owner = owner
        self.__balance = initial_balance  # private 변수

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount
            return True
        return False

    def get_balance(self):
        return self.__balance  # 안전한 접근 방법

# 사용
account = BankAccount("태수", 1000)
account.deposit(500)
print(account.get_balance())  # 1500
# account.__balance  # 오류! 직접 접근 불가
```

### 2. 상속 예시
```python
class Vehicle:  # 부모 클래스
    def __init__(self, brand, year):
        self.brand = brand
        self.year = year

    def start(self):
        return f"{self.brand} 시동 걸림"

class Car(Vehicle):  # 자식 클래스
    def __init__(self, brand, year, doors):
        super().__init__(brand, year)  # 부모 생성자 호출
        self.doors = doors

    def honk(self):
        return "빵빵!"

class Motorcycle(Vehicle):
    def __init__(self, brand, year, engine_size):
        super().__init__(brand, year)
        self.engine_size = engine_size

    def wheelie(self):
        return "앞바퀴 들어올림!"

# 사용
car = Car("현대", 2023, 4)
moto = Motorcycle("야마하", 2022, 250)

print(car.start())     # "현대 시동 걸림" (상속받은 메서드)
print(car.honk())      # "빵빵!" (고유 메서드)
print(moto.wheelie())  # "앞바퀴 들어올림!"
```

### 3. 다형성 예시
```python
class Shape:
    def area(self):
        pass

    def perimeter(self):
        pass

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14159 * self.radius ** 2

    def perimeter(self):
        return 2 * 3.14159 * self.radius

# 다형성 활용
def print_shape_info(shape):
    print(f"면적: {shape.area()}")      # 같은 메서드명
    print(f"둘레: {shape.perimeter()}")  # 다른 동작

rect = Rectangle(5, 3)
circle = Circle(4)

print_shape_info(rect)   # 직사각형 계산
print_shape_info(circle) # 원 계산
```

### 4. 추상화 예시
```python
from abc import ABC, abstractmethod

class PaymentProcessor(ABC):  # 추상 클래스
    @abstractmethod
    def process_payment(self, amount):
        pass

    @abstractmethod
    def validate_payment(self, payment_info):
        pass

class CreditCardProcessor(PaymentProcessor):
    def process_payment(self, amount):
        return f"신용카드로 {amount}원 결제 완료"

    def validate_payment(self, card_info):
        return len(card_info) == 16

class KakaoPayProcessor(PaymentProcessor):
    def process_payment(self, amount):
        return f"카카오페이로 {amount}원 결제 완료"

    def validate_payment(self, phone_number):
        return len(phone_number) == 11

# 사용자는 구체적인 구현을 몰라도 됨
def make_payment(processor, amount, payment_info):
    if processor.validate_payment(payment_info):
        return processor.process_payment(amount)
    return "결제 정보가 유효하지 않습니다"

credit = CreditCardProcessor()
kakao = KakaoPayProcessor()

print(make_payment(credit, 10000, "1234567890123456"))
print(make_payment(kakao, 5000, "01012345678"))
```

## 🎮 실전 예시: 게임 캐릭터 시스템

```python
class Character:
    def __init__(self, name, hp, mp):
        self.name = name
        self._hp = hp  # protected
        self._mp = mp
        self._level = 1

    def attack(self):
        return f"{self.name}이(가) 공격!"

    def level_up(self):
        self._level += 1
        self._hp += 10
        self._mp += 5

class Warrior(Character):
    def __init__(self, name):
        super().__init__(name, 100, 20)
        self.weapon = "검"

    def attack(self):  # 오버라이딩
        return f"{self.name}이(가) {self.weapon}으로 강력한 공격!"

    def shield_defense(self):
        return f"{self.name}이(가) 방패로 방어!"

class Mage(Character):
    def __init__(self, name):
        super().__init__(name, 60, 80)
        self.spell_book = ["파이어볼", "아이스볼트"]

    def attack(self):
        return f"{self.name}이(가) 마법으로 공격!"

    def cast_spell(self, spell):
        if spell in self.spell_book:
            return f"{self.name}이(가) {spell} 시전!"
        return "모르는 마법입니다"

# 게임 실행
warrior = Warrior("태수전사")
mage = Mage("태수마법사")

characters = [warrior, mage]

# 다형성 활용 - 같은 메서드, 다른 동작
for char in characters:
    print(char.attack())  
    char.level_up()
    print(f"{char.name} 레벨업! 현재 레벨: {char._level}")
```

이렇게 OOP를 쓰면 코드가 훨씬 체계적이고 확장하기 쉬워져. 새로운 캐릭터 클래스를 추가하거나 기능을 변경할 때도 기존 코드를 크게 건드리지 않아도 되거든."
